pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }
    function testRegression_property() public {
        address token = address(new Token());
        address alice = address(0x123);
        address bob = address(0x456);
        uint[] memory amounts = new uint[](1);
        amounts[0] = 100;
        address[] memory recipients = new address[](1);
        recipients[0] = bob;
        Token t = Token(token);
        assertEq(t.successFlag(), false);
        c.transfer(alice, token, recipients, amounts);
        assertEq(t.successFlag(), true);
    }
}

contract Token {
    bool public successFlag;
    function transferFrom(address, address, uint256) external returns (bool) {
        successFlag = true;
        return true;
    }
}
